pub fn vanilla_attribute_type(id: i32) -> Option<&'static AttributeTypeCatalogEntry> {
    VANILLA_ATTRIBUTE_TYPES.get(usize::try_from(id).ok()?)
}

pub fn vanilla_attribute_type_for_resource_id(
    resource_id: &str,
) -> Option<&'static AttributeTypeCatalogEntry> {
    VANILLA_ATTRIBUTE_TYPES
        .iter()
        .find(|entry| entry.resource_id == resource_id)
}

#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn attribute_catalog_is_complete_contiguous_and_unique() {
        assert_eq!(VANILLA_ATTRIBUTE_TYPES.len(), 35);
        let mut constants = HashSet::new();
        let mut resources = HashSet::new();
        for (id, entry) in VANILLA_ATTRIBUTE_TYPES.iter().enumerate() {
            assert_eq!(entry.id, id as i32);
            assert!(constants.insert(entry.constant_name));
            assert!(resources.insert(entry.resource_id));
        }
        assert_eq!(
            VANILLA_ATTRIBUTE_TYPES
                .iter()
                .filter(|entry| entry.sentiment == AttributeSentiment::Negative)
                .count(),
            2
        );
        assert_eq!(
            VANILLA_ATTRIBUTE_TYPES
                .iter()
                .filter(|entry| entry.sentiment == AttributeSentiment::Neutral)
                .count(),
            4
        );
        assert_eq!(
            VANILLA_ATTRIBUTE_TYPES
                .iter()
                .filter(|entry| entry.syncable)
                .count(),
            27
        );
    }

    #[test]
    fn attribute_catalog_preserves_vanilla_order_and_metadata() {
        assert_eq!(VANILLA_ATTRIBUTE_ATTACK_DAMAGE_ID, 2);
        assert_eq!(VANILLA_ATTRIBUTE_SCALE_ID, 25);
        assert_eq!(VANILLA_ATTRIBUTE_WAYPOINT_RECEIVE_RANGE_ID, 34);
        assert_eq!(
            vanilla_attribute_type(7).unwrap().sentiment,
            AttributeSentiment::Negative
        );
        assert_eq!(
            vanilla_attribute_type(25).unwrap().sentiment,
            AttributeSentiment::Neutral
        );
        assert_eq!(
            vanilla_attribute_type_for_resource_id("minecraft:attack_speed")
                .unwrap()
                .id,
            4
        );
        assert_eq!(vanilla_attribute_type(-1), None);
        assert_eq!(vanilla_attribute_type(35), None);
    }

    #[test]
    fn production_sources_do_not_redeclare_attribute_catalog_lookups() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/attribute_types.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                let production = source.split("#[cfg(test)]").next().unwrap_or(&source);
                if production.contains("struct VanillaAttribute")
                    || production.contains("fn vanilla_attribute(")
                    || production.contains("fn vanilla_attribute_for_key(")
                    || production.contains("fn vanilla_attribute_id_for_key(")
                    || production.contains("fn vanilla_attribute_resource_id(")
                {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel attribute catalog lookup bridges: {violations:?}"
        );
    }

    #[test]
    fn attribute_fixtures_do_not_restore_fixed_scale_or_max_health_ids() {
        let player_pose = include_str!(
            "../../bbb-world/src/entities/tests/player_pose_and_sleeping_projection.rs"
        );
        let creature_bounds =
            include_str!("../../bbb-world/src/entities/tests/creature_pick_bounds_projection.rs");
        let specialized_bounds = include_str!(
            "../../bbb-world/src/entities/tests/specialized_pick_bounds_and_render_scale.rs"
        );
        let native_scene = include_str!("../../bbb-native/src/entity_scene/tests.rs");
        for source in [
            player_pose,
            creature_bounds,
            specialized_bounds,
            native_scene,
        ] {
            assert!(source.contains("VANILLA_ATTRIBUTE_SCALE_ID"));
            assert!(!source.contains("const VANILLA_ATTRIBUTE_SCALE_ID"));
        }
        let local_player = include_str!("../../bbb-world/src/client/local_player.rs");
        assert!(local_player.contains("VANILLA_ATTRIBUTE_MAX_HEALTH_ID"));
        assert!(!local_player.contains("const VANILLA_ATTRIBUTE_MAX_HEALTH_ID"));
    }
}
